// ---------------------------------------------------------------------------
// axios: a unit test never reaches the network.
//
// This is not tidiness. A suite that reaches the network does not fail, it
// HANGS. verifyPasscode mints an access token on success (the reference's
// refreshThenProceed), and on an app with a WIRED refresh operation that is a
// real request — and refreshSession is single-flight, so the promise that never
// settles is handed to every later caller. One such call timed four tests out
// at 30s each, and the CI pipeline aborts before the scan stage when the suite
// fails, so nothing got scanned at all.
//
// The default is an immediate network-shaped rejection, which is a state the
// app already handles deliberately: refresh reports unavailable rather than
// reauth, so a vault unlock still succeeds and the 401 interceptor owns the
// retry. A suite that wants specific responses mocks axios itself, and a
// file-local jest.mock overrides this one.
// ---------------------------------------------------------------------------
jest.mock('axios', () => {
  const offline = () => {
    const e = new Error('jest: no network — mock axios in this suite to assert on responses');
    return e;
  };
  const instance = {
    request: async () => { throw offline(); },
    get: async () => { throw offline(); },
    post: async () => { throw offline(); },
    put: async () => { throw offline(); },
    patch: async () => { throw offline(); },
    delete: async () => { throw offline(); },
    // both arities: the client registers (onFulfilled, onRejected) and also
    // (undefined, onRejected) for the 401 replay
    interceptors: {
      request: { use: () => undefined },
      response: { use: () => undefined },
    },
    defaults: { headers: { common: {} } },
  };
  const isAxiosError = (e) => Boolean(e && typeof e === 'object' && 'response' in e);
  return {
    __esModule: true,
    default: { create: () => instance, isAxiosError, ...instance },
    isAxiosError,
    AxiosError: Error,
  };
});

