//
// Each is a TurboModule that calls getEnforcing() at import time, so under jest
// — where there is no native binary — merely importing a screen throws
// 'RNDocumentPicker could not be found' and the whole suite fails to RUN.
// That is how 19 of 23 generated suites were red while reporting 9 passing
// tests: the failures were collection errors, not assertions.
//
// virtual:true so a mock for a package this particular app does not install
// is harmless. Listing them all here keeps the setup correct for every
// combination of feature flags rather than the one that was generated today.
// ---------------------------------------------------------------------------
const mockView = (name) => () => {
  const React = require('react');
  const { View } = require('react-native');
  const C = (props) => React.createElement(View, props);
  C.displayName = name;
  return { __esModule: true, default: C };
};

